#!/usr/bin/env python3
"""Build a portable offline scroll review package for a VACE CoinVE run."""
import argparse, csv, html, json, shutil
from pathlib import Path

def main():
    ap=argparse.ArgumentParser(); ap.add_argument('--run',type=Path,required=True); ap.add_argument('--output',type=Path,required=True); args=ap.parse_args()
    run=json.loads((args.run/'run_manifest.json').read_text())
    out=args.output; media=out/'media'; media.mkdir(parents=True,exist_ok=True)
    records=[]
    for chain in run['chains']:
        sid=chain['sample_id']
        source=Path(chain['rounds'][0]['input_video'])
        src_name=f'{sid}__source.mp4'; shutil.copy2(source,media/src_name)
        rounds=[]
        for rr in chain['rounds']:
            name=f'{sid}__round_{int(rr["round_index"]):02d}.mp4'; shutil.copy2(rr['output_video'],media/name)
            rounds.append({'round_index':rr['round_index'],'instruction':rr['instruction'],'input_video':rr['input_video'],'video':f'media/{name}'})
        records.append({'sample_id':sid,'sample_rank':chain['sample_rank'],'source':f'media/{src_name}','rounds':rounds})
    (out/'review_manifest.json').write_text(json.dumps({'schema_version':'coinve.vace.review.v1','run':run,'records':records},ensure_ascii=False,indent=2)+'\n')
    cards=[]
    for rec in records:
        rounds=''.join(f'''<article class="round"><h3>Round {r['round_index']}: {html.escape(r['instruction'])}</h3><div class="videos"><div><label>Input</label><video controls preload="metadata" src="{html.escape(rec['source'] if r['round_index']==1 else f"media/{rec['sample_id']}__round_{int(r['round_index'])-1:02d}.mp4")}"></video></div><div><label>VACE output</label><video controls preload="metadata" src="{html.escape(r['video'])}"></video></div></div><p class="score" data-id="{rec['sample_id']}-round-{int(r['round_index']):02d}">Gemini score: pending</p><textarea placeholder="Manual audit notes"></textarea></article>''' for r in rec['rounds'])
        cards.append(f'<section class="chain"><h2>{html.escape(rec["sample_id"])} <small>rank {rec["sample_rank"]}</small></h2>{rounds}</section>')
    page='''<!doctype html><meta charset="utf-8"><title>VACE CoinVE Multi-round Review</title><style>body{font:15px system-ui;background:#111;color:#eee;max-width:1200px;margin:auto;padding:24px}h1{color:#9fdfb0}.chain{border:1px solid #444;margin:22px 0;padding:16px}.round{border-top:1px solid #555;padding:12px 0}.videos{display:flex;gap:18px}.videos>div{flex:1}label{display:block;color:#aaa;margin-bottom:5px}video{width:100%;background:#000}textarea{width:100%;min-height:45px;background:#222;color:#eee}small{color:#aaa;font-weight:normal}.score{color:#f5cf7a}</style><h1>VACE · CoinVE multi-round offline review</h1><p>Generated by Wan2.1-VACE-1.3B, 25 steps. Review source → each successive round. Gemini scores are inserted after API evaluation; manual notes remain local to this package.</p><input id="q" placeholder="filter sample or instruction" oninput="f()">''' + ''.join(cards) + '''<script>function f(){let q=document.querySelector('#q').value.toLowerCase();document.querySelectorAll('.chain').forEach(x=>x.style.display=x.innerText.toLowerCase().includes(q)?'':'none')}</script>'''
    (out/'index.html').write_text(page)
    (out/'README.md').write_text('# VACE CoinVE 多轮编辑离线审核包\n\n解压后用浏览器打开 `index.html`。每条链按 source → round 逐轮展示；视频和 manifest 均为本地副本，不含模型权重或 API 凭据。\n')
    print(f'package: {out} ({len(records)} chains)')
if __name__=='__main__': main()
